<template>
    <component v-if="!asChild" :is="as" :class="cx('root')" :type="as === 'BUTTON' || as === 'button' ? 'button' : undefined" v-bind="attrs" @click="onClick">
        <slot />
    </component>
    <slot v-else :a11yAttrs="a11yAttrs" :class="cx('root')" :onClick="onClick" />
</template>

<script>
import { mergeProps } from 'vue';
import BaseSidebarTrigger from './BaseSidebarTrigger.vue';

export default {
    name: 'SidebarTrigger',
    extends: BaseSidebarTrigger,
    inheritAttrs: false,
    inject: {
        $pcSidebar: { default: null },
        $pcSidebarLayout: { default: null }
    },
    methods: {
        onClick(event) {
            this.$pcSidebarLayout?.notifyTriggerClick?.(event);

            if (this.$pcSidebar) {
                this.$pcSidebar.toggle(event);

                return;
            }

            if (this.$pcSidebarLayout) {
                this.$pcSidebarLayout.toggleSidebar(this.target, event);
            }
        }
    },
    computed: {
        controlled() {
            if (this.$pcSidebar) return { id: this.$pcSidebar.id, open: this.$pcSidebar.d_open };

            const registry = this.$pcSidebarLayout?.getSidebarEntries?.();

            if (!registry) return null;

            const id = this.target ?? registry.keys().next().value;
            const entry = registry.get(id);

            return entry ? { id, open: entry.open } : null;
        },
        a11yAttrs() {
            const sidebarPart = this.$pcSidebar?.getSectionAttrs('trigger') ?? {};

            return {
                ...sidebarPart,
                'data-pc-name': 'sidebartrigger',
                'data-pc-section': 'root',
                'aria-expanded': this.controlled ? (this.controlled.open ? 'true' : 'false') : undefined,
                'aria-controls': this.controlled?.id
            };
        },
        attrs() {
            return mergeProps(this.$attrs, this.a11yAttrs, this.ptmi('root'));
        }
    }
};
</script>
